import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 全册易错点 · 第1–24课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第二册：实践与进步 · 全册易错点 · 第1–24课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-2/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册易错点","link":"/life/english/new-concept/book-2/mistakes"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第25–49课","link":"/life/english/new-concept/book-2/mistakes-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册易错点","link":"/life/english/new-concept/book-2/mistakes"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第25–49课","link":"/life/english/new-concept/book-2/mistakes-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/mistakes-part-01.md","filePath":"life/english/new-concept/book-2/mistakes-part-01.md"}'),l={name:"life/english/new-concept/book-2/mistakes-part-01.md"};function s(i,e,r,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-全册易错点-·-第1–24课" tabindex="-1">第二册：实践与进步 · 全册易错点 · 第1–24课 <a class="header-anchor" href="#第二册-实践与进步-·-全册易错点-·-第1–24课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册易错点 · 第1–24课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="第二册-实践与进步-·-全册易错点" tabindex="-1">第二册：实践与进步 · 全册易错点 <a class="header-anchor" href="#第二册-实践与进步-·-全册易错点" aria-label="Permalink to &quot;第二册：实践与进步 · 全册易错点 {#第二册-实践与进步-·-全册易错点}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="l1-·-一般过去时与事件顺序" tabindex="-1">L1 · 一般过去时与事件顺序 <a class="header-anchor" href="#l1-·-一般过去时与事件顺序" aria-label="Permalink to &quot;L1 · 一般过去时与事件顺序 {#l1-·-一般过去时与事件顺序}&quot;">​</a></h2><p>quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</p><p><strong>对照例句：</strong> Maya closed her book quietly after the discussion.</p><p>Maya 是主语，closed 是过去式谓语，her book 是宾语，quietly 是方式状语，after 短语标记时间。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-001">回看讲解和练习</a></p><h2 id="l2-·-一般现在时与习惯" tabindex="-1">L2 · 一般现在时与习惯 <a class="header-anchor" href="#l2-·-一般现在时与习惯" aria-label="Permalink to &quot;L2 · 一般现在时与习惯 {#l2-·-一般现在时与习惯}&quot;">​</a></h2><p>He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</p><p><strong>对照例句：</strong> Leo usually eats breakfast before seven.</p><p>Leo 是单数主语，eats 是习惯性动作，usually 位于实义动词前，before seven 给出时间边界。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-002">回看讲解和练习</a></p><h2 id="l3-·-动词、宾语与补足语" tabindex="-1">L3 · 动词、宾语与补足语 <a class="header-anchor" href="#l3-·-动词、宾语与补足语" aria-label="Permalink to &quot;L3 · 动词、宾语与补足语 {#l3-·-动词、宾语与补足语}&quot;">​</a></h2><p>send a postcard for her 表示替她寄，不一定表示寄给她；寄给她用 to her。</p><p><strong>对照例句：</strong> Nina sent her uncle a postcard from the island.</p><p>Nina 是主语，sent 是 send 的过去式，her uncle 是间接宾语，a postcard 是直接宾语，from 短语说明寄出地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-003">回看讲解和练习</a></p><h2 id="l4-·-现在完成时与过去时间" tabindex="-1">L4 · 现在完成时与过去时间 <a class="header-anchor" href="#l4-·-现在完成时与过去时间" aria-label="Permalink to &quot;L4 · 现在完成时与过去时间 {#l4-·-现在完成时与过去时间}&quot;">​</a></h2><p>has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</p><p><strong>对照例句：</strong> Iris has visited three coastal towns this month.</p><p>has visited 表示本月到现在的经历；three coastal towns 是已完成的数量，this month 在此被理解为尚未结束的时间段。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-004">回看讲解和练习</a></p><h2 id="l5-·-现在完成时与过去时间" tabindex="-1">L5 · 现在完成时与过去时间 <a class="header-anchor" href="#l5-·-现在完成时与过去时间" aria-label="Permalink to &quot;L5 · 现在完成时与过去时间 {#l5-·-现在完成时与过去时间}&quot;">​</a></h2><p>receive 不等于 send；已收到用 have received，不要写 have receive。</p><p><strong>对照例句：</strong> Our studio has received six messages today.</p><p>Our studio 是整体单数主语，所以用 has；six messages 表示累计结果，today 的时间范围延伸到现在。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-005">回看讲解和练习</a></p><h2 id="l6-·-冠词与可数性" tabindex="-1">L6 · 冠词与可数性 <a class="header-anchor" href="#l6-·-冠词与可数性" aria-label="Permalink to &quot;L6 · 冠词与可数性 {#l6-·-冠词与可数性}&quot;">​</a></h2><p>a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</p><p><strong>对照例句：</strong> A neighbour brought me some bread after the storm.</p><p>A neighbour 首次引入人物；some bread 是不可数名词短语；brought 带 me 与 some bread 两个宾语。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-006">回看讲解和练习</a></p><h2 id="l7-·-过去进行时与叙事背景" tabindex="-1">L7 · 过去进行时与叙事背景 <a class="header-anchor" href="#l7-·-过去进行时与叙事背景" aria-label="Permalink to &quot;L7 · 过去进行时与叙事背景 {#l7-·-过去进行时与叙事背景}&quot;">​</a></h2><p>The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</p><p><strong>对照例句：</strong> The guards were checking the gate when the parcel arrived.</p><p>主句 were checking 是背景，when 从句 arrived 是介入事件；guards 是复数，所以不能用 was。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-007">回看讲解和练习</a></p><h2 id="l8-·-比较级与比较范围" tabindex="-1">L8 · 比较级与比较范围 <a class="header-anchor" href="#l8-·-比较级与比较范围" aria-label="Permalink to &quot;L8 · 比较级与比较范围 {#l8-·-比较级与比较范围}&quot;">​</a></h2><p>Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</p><p><strong>对照例句：</strong> Lena&#39;s garden is smaller but neater than mine.</p><p>smaller 与 neater 是并列比较级；than mine 中 mine 代替 my garden，比较的是花园而非主人。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-008">回看讲解和练习</a></p><h2 id="l9-·-一般过去时与事件顺序" tabindex="-1">L9 · 一般过去时与事件顺序 <a class="header-anchor" href="#l9-·-一般过去时与事件顺序" aria-label="Permalink to &quot;L9 · 一般过去时与事件顺序 {#l9-·-一般过去时与事件顺序}&quot;">​</a></h2><p>reach the square 不加 to；arrive at the square 才需要 at。</p><p><strong>对照例句：</strong> The crowd reached the square at half past eight.</p><p>reached 是及物动词，后直接接 the square；at half past eight 是具体钟点，不用 in。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-009">回看讲解和练习</a></p><h2 id="l10-·-被动语态与信息重点" tabindex="-1">L10 · 被动语态与信息重点 <a class="header-anchor" href="#l10-·-被动语态与信息重点" aria-label="Permalink to &quot;L10 · 被动语态与信息重点 {#l10-·-被动语态与信息重点}&quot;">​</a></h2><p>The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</p><p><strong>对照例句：</strong> The old guitar was repaired by a local technician.</p><p>The old guitar 是承受动作的主语，was repaired 是一般过去时被动，by 短语指出执行者。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-010">回看讲解和练习</a></p><h2 id="l11-·-现在完成时与过去时间" tabindex="-1">L11 · 现在完成时与过去时间 <a class="header-anchor" href="#l11-·-现在完成时与过去时间" aria-label="Permalink to &quot;L11 · 现在完成时与过去时间 {#l11-·-现在完成时与过去时间}&quot;">​</a></h2><p>borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</p><p><strong>对照例句：</strong> Ravi has lent me his bicycle for the weekend.</p><p>Ravi 是借出者，has lent 是完成时，me 是接收者，for the weekend 说明借用时段。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-011">回看讲解和练习</a></p><h2 id="l12-·-将来表达与安排" tabindex="-1">L12 · 将来表达与安排 <a class="header-anchor" href="#l12-·-将来表达与安排" aria-label="Permalink to &quot;L12 · 将来表达与安排 {#l12-·-将来表达与安排}&quot;">​</a></h2><p>sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</p><p><strong>对照例句：</strong> Our neighbour is sailing to the island on Friday.</p><p>is sailing 是现在进行时表将来安排，on Friday 明确日期，to the island 表示目的地。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-012">回看讲解和练习</a></p><h2 id="l13-·-将来进行时与过程" tabindex="-1">L13 · 将来进行时与过程 <a class="header-anchor" href="#l13-·-将来进行时与过程" aria-label="Permalink to &quot;L13 · 将来进行时与过程 {#l13-·-将来进行时与过程}&quot;">​</a></h2><p>will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</p><p><strong>对照例句：</strong> At seven tomorrow, the band will be rehearsing in the hall.</p><p>At seven tomorrow 建立未来参照点，will be rehearsing 表示该时刻正在进行的活动，in the hall 是地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-013">回看讲解和练习</a></p><h2 id="l14-·-过去进行时与叙事背景" tabindex="-1">L14 · 过去进行时与叙事背景 <a class="header-anchor" href="#l14-·-过去进行时与叙事背景" aria-label="Permalink to &quot;L14 · 过去进行时与叙事背景 {#l14-·-过去进行时与叙事背景}&quot;">​</a></h2><p>explain me the route 不符合常见搭配；用 explain the route to me。</p><p><strong>对照例句：</strong> I was looking for the station when a cyclist offered help.</p><p>I was looking 是持续背景，when 引出 offered；offer help 中 help 是不可数名词。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-014">回看讲解和练习</a></p><h2 id="l15-·-间接引语与视角转换" tabindex="-1">L15 · 间接引语与视角转换 <a class="header-anchor" href="#l15-·-间接引语与视角转换" aria-label="Permalink to &quot;L15 · 间接引语与视角转换 {#l15-·-间接引语与视角转换}&quot;">​</a></h2><p>said Hana that 错误；说给某人听可用 said to Hana 或 told Hana。</p><p><strong>对照例句：</strong> The manager told Hana that her work was excellent.</p><p>told 的宾语是 Hana，that 引出所说内容；her 指 Hana，was 在过去视角下转述评价。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-015">回看讲解和练习</a></p><h2 id="l16-·-情态动词的意义与形式" tabindex="-1">L16 · 情态动词的意义与形式 <a class="header-anchor" href="#l16-·-情态动词的意义与形式" aria-label="Permalink to &quot;L16 · 情态动词的意义与形式 {#l16-·-情态动词的意义与形式}&quot;">​</a></h2><p>Could you to move 多了 to；could 是情态动词，后接原形。</p><p><strong>对照例句：</strong> Could you move your car away from the entrance, please?</p><p>Could 位于主语 you 前形成问句，后接 move 原形；away from 引出应远离的位置，please 缓和语气。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-016">回看讲解和练习</a></p><h2 id="l17-·-一般现在时与习惯" tabindex="-1">L17 · 一般现在时与习惯 <a class="header-anchor" href="#l17-·-一般现在时与习惯" aria-label="Permalink to &quot;L17 · 一般现在时与习惯 {#l17-·-一般现在时与习惯}&quot;">​</a></h2><p>looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</p><p><strong>对照例句：</strong> My aunt always looks cheerful before a performance.</p><p>My aunt 是主语，looks 是系动词，cheerful 是表语；always 表示频率，不修饰形容词程度。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-017">回看讲解和练习</a></p><h2 id="l18-·-一般现在时与习惯" tabindex="-1">L18 · 一般现在时与习惯 <a class="header-anchor" href="#l18-·-一般现在时与习惯" aria-label="Permalink to &quot;L18 · 一般现在时与习惯 {#l18-·-一般现在时与习惯}&quot;">​</a></h2><p>Does the dog hides 错误；does 出现后使用 hide。</p><p><strong>对照例句：</strong> Our dog often hides my bag under the sofa.</p><p>often 放在实义动词 hides 前；my bag 是宾语，under the sofa 是地点，第三人称单数动词加 -s。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-018">回看讲解和练习</a></p><h2 id="l19-·-情态动词的意义与形式" tabindex="-1">L19 · 情态动词的意义与形式 <a class="header-anchor" href="#l19-·-情态动词的意义与形式" aria-label="Permalink to &quot;L19 · 情态动词的意义与形式 {#l19-·-情态动词的意义与形式}&quot;">​</a></h2><p>may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p><p><strong>对照例句：</strong> Two seats may become available if someone cancels.</p><p>may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-019">回看讲解和练习</a></p><h2 id="l20-·-动名词与动词搭配" tabindex="-1">L20 · 动名词与动词搭配 <a class="header-anchor" href="#l20-·-动名词与动词搭配" aria-label="Permalink to &quot;L20 · 动名词与动词搭配 {#l20-·-动名词与动词搭配}&quot;">​</a></h2><p>enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p><p><strong>对照例句：</strong> Ben enjoys fishing beside the old bridge.</p><p>enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-020">回看讲解和练习</a></p><h2 id="l21-·-被动语态与信息重点" tabindex="-1">L21 · 被动语态与信息重点 <a class="header-anchor" href="#l21-·-被动语态与信息重点" aria-label="Permalink to &quot;L21 · 被动语态与信息重点 {#l21-·-被动语态与信息重点}&quot;">​</a></h2><p>noise 与 noisy 词性不同：traffic noise 是噪声，a noisy street 是吵闹的街道。</p><p><strong>对照例句：</strong> Our sleep is disturbed by early flights.</p><p>Our sleep 是承受影响的主语，is disturbed 是现在时被动，by early flights 表原因来源。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-021">回看讲解和练习</a></p><h2 id="l22-·-动词、宾语与补足语" tabindex="-1">L22 · 动词、宾语与补足语 <a class="header-anchor" href="#l22-·-动词、宾语与补足语" aria-label="Permalink to &quot;L22 · 动词、宾语与补足语 {#l22-·-动词、宾语与补足语}&quot;">​</a></h2><p>reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p><p><strong>对照例句：</strong> A walker replied to the message inside the bottle.</p><p>replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-022">回看讲解和练习</a></p><h2 id="l23-·-被动语态与信息重点" tabindex="-1">L23 · 被动语态与信息重点 <a class="header-anchor" href="#l23-·-被动语态与信息重点" aria-label="Permalink to &quot;L23 · 被动语态与信息重点 {#l23-·-被动语态与信息重点}&quot;">​</a></h2><p>is building 表主动建造，不能让 footpath 像施工者一样行动；此处用 is being built。</p><p><strong>对照例句：</strong> A new footpath is being built behind our house.</p><p>A new footpath 是主语，is being built 是现在进行时被动；behind our house 是地点，不是动作执行者。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-023">回看讲解和练习</a></p><h2 id="l24-·-情态动词的意义与形式" tabindex="-1">L24 · 情态动词的意义与形式 <a class="header-anchor" href="#l24-·-情态动词的意义与形式" aria-label="Permalink to &quot;L24 · 情态动词的意义与形式 {#l24-·-情态动词的意义与形式}&quot;">​</a></h2><p>someone 作主语按单数处理；someone have 应改为 someone has。</p><p><strong>对照例句：</strong> I lost my wallet, but someone returned it that evening.</p><p>lost 与 returned 同为过去式推进事件；someone 是未知身份的人，it 指 wallet，but 标记转折。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-024">回看讲解和练习</a></p>',125)])])}const f=a(l,[["render",s]]);export{g as __pageData,f as default};
